{
  "anchor_page_id": "40015",
  "rationale": "Page 40015, 'Consent Needed for Adding Support Needs', directly addresses the core intent of the query by detailing the 'consent and verification rules required when adding, changing, or deleting customer support needs.' It provides foundational information on identity verification and consent, which are prerequisites to the actual process of adding a support need. Other pages are either too specific (Compromised CVP, Talking ATMs) or focus on the procedural 'how-to' rather than the overarching requirements (How To Add a Support Need in MCP)."
}

{
  "expanded_page_ids": [
    "40022"
  ],
  "rationale": "Selected 'page_id_40022' because its summary explicitly mentions 'verification requirements needed before taking actions to record, update, or remove support needs' and its primary intent includes 'Check support need verification requirements', which directly aligns with the query 'required verification add support need'. 'page_id_40021' was excluded as its focus is on recording support needs from written communications, not the general verification process for adding support needs, which is a key part of the query."
}

{
  "definitions": [
    {
      "meaning": "This is the required verification level for Personal Banking and Fraud Colleagues when adding a support need.",
      "page_id": "40015",
      "phrase": "Minimum Standard Risk"
    },
    {
      "meaning": "This indicates no verification is required when adding a support need if the customer is unable to give consent (e.g., due to reduced mental capacity or exceptional circumstances), or when the customer is not present (e.g., informed by a third party).",
      "page_id": "40015",
      "phrase": "Non-verifiable"
    },
    {
      "meaning": "This is a verification requirement for Community Bank Colleagues to add a support need if the customer is present in branch and able to give consent.",
      "page_id": "40015",
      "phrase": "Customer must be identifiable"
    },
    {
      "meaning": "This is a verification requirement for Community Bank Colleagues when adding a support need if the customer either phones the branch and gives consent or is phoned by a branch colleague and gives consent.",
      "page_id": "40015",
      "phrase": "Verify customer using CVP questions"
    }
  ]
}
